import { sql } from "drizzle-orm";
import { check, index, sqliteTable, text } from "drizzle-orm/sqlite-core";

/**
 * Complete Scryfall card payload retained for API responses and future features.
 * Required searchable properties are enforced separately by generated columns.
 */
export type ScryfallCardJson = Record<string, unknown>;

/**
 * Stores one Scryfall printing while deriving identity columns from its JSON.
 *
 * The Scryfall ID is the stable primary key used to make repeated imports
 * idempotent. Name, set, and collector number are generated by SQLite from the
 * canonical payload, preventing searchable fields from drifting from stored JSON.
 * Indexes support name lookup and the preferred set/collector-number identity;
 * check constraints reject payloads whose required identity values are empty.
 */
export const cards = sqliteTable(
	"cards",
	{
		id: text().primaryKey(),
		json: text({ mode: "json" }).$type<ScryfallCardJson>().notNull(),
		name: text().generatedAlwaysAs(sql`json_extract(json, '$.name')`).notNull(),
		set: text().generatedAlwaysAs(sql`json_extract(json, '$.set')`).notNull(),
		collectorNumber: text("collector_number")
			.generatedAlwaysAs(sql`json_extract(json, '$.collector_number')`)
			.notNull(),
	},
	(table) => [
		index("cards_name_idx").on(table.name),
		index("cards_set_collector_number_idx").on(
			table.set,
			sql`${table.collectorNumber} collate nocase`,
		),
		check("cards_name_min_length", sql`length(${table.name}) >= 1`),
		check("cards_set_min_length", sql`length(${table.set}) >= 1`),
		check(
			"cards_collectorNumber_min_length",
			sql`length(${table.collectorNumber}) >= 1`,
		),
	],
);
